class Solution { private int gcd(int a,int b){while(b!=0){int temporary=a%b;a=b;b=temporary;}return a;}public long countPairs(int[] nums,int k){Map<Integer,Integer> frequency=new HashMap<>();long answer=0;for(int value:nums){int current=gcd(value,k);for(Map.Entry<Integer,Integer> entry:frequency.entrySet())if((long)current*entry.getKey()%k==0)answer+=entry.getValue();frequency.merge(current,1,Integer::sum);}return answer;} }
